<script>
  import {UNIT_DECISIONS,UNITS_MEASUREMENT_MISSION,answerForUnitCase,auditEntry} from '../lib/game/units-measurement-mission.js';
  import { recordCompletion } from '../lib/game/progress.js';
  import MissionMasthead from '../lib/components/game/MissionMasthead.svelte';
  const steps=['dimension','value','decision'];
  let caseIndex=0,step='dimension',selected='',checked=false,correct=false,completed=[];
  $: caseRecord=UNITS_MEASUREMENT_MISSION.cases[caseIndex]; $: missionComplete=completed.length===UNITS_MEASUREMENT_MISSION.cases.length; $: stepIndex=steps.indexOf(step);
  $: answer=answerForUnitCase(caseRecord,step); $: options=caseRecord?(step==='dimension'?caseRecord.dimensionOptions.map(value=>({value,label:value,note:`Does ${caseRecord.rawUnit} measure ${value}?`})):step==='value'?valueOptions(caseRecord):UNIT_DECISIONS):[];
  $: progress=Math.round(((completed.length*3+stepIndex+(correct?1:0))/(UNITS_MEASUREMENT_MISSION.cases.length*3))*100); $: audit=caseRecord?auditEntry(caseRecord):null;
  $: prompt=step==='dimension'?'What quantity does the source unit measure?':step==='value'?`What belongs in ${caseRecord.field}?`:'What is the safe treatment?';
  $: theory=step==='dimension'?'A measurement needs both a number and a unit. Convert only when source and target units measure the same kind of quantity.':step==='value'?'A conversion changes the numerical value and unit together while preserving the quantity. Apply the declared factor once.':'Normalisation adds a comparable value; it does not erase the raw measurement or its provenance.';
  function valueOptions(item){if(item.normalisedValue===null)return[{value:'not convertible',label:'Not convertible',note:`${item.rawUnit} and ${item.targetUnit} describe different quantities`},{value:`28 ${item.targetUnit}`,label:`28 ${item.targetUnit}`,note:'copy the number and change only the label'},{value:`0.28 ${item.targetUnit}`,label:`0.28 ${item.targetUnit}`,note:'divide by 100 despite the dimension change'}];const candidates=[{value:item.displayValue,label:item.displayValue,note:item.factor},{value:`${item.rawValue.toLocaleString('en-GB')} ${item.targetUnit}`,label:`${item.rawValue.toLocaleString('en-GB')} ${item.targetUnit}`,note:'change the label but not the number'},{value:`${(item.rawValue*1000).toLocaleString('en-GB')} ${item.targetUnit}`,label:`${(item.rawValue*1000).toLocaleString('en-GB')} ${item.targetUnit}`,note:'apply a factor of 1,000 in the other direction'}];return candidates.filter((option,index,list)=>list.findIndex(candidate=>candidate.value===option.value)===index)}
  function choose(value){if(correct)return;selected=value;checked=true;correct=value===answer}
  function advance(){if(!correct)return;if(stepIndex<steps.length-1){step=steps[stepIndex+1];selected='';checked=false;correct=false;return}completed=[...completed,audit];caseIndex+=1;step='dimension';selected='';checked=false;correct=false}
  function resetMission(){caseIndex=0;step='dimension';selected='';checked=false;correct=false;completed=[]}
  function explanation(){return step==='dimension'?caseRecord.dimensionExplanation:step==='value'?caseRecord.valueExplanation:caseRecord.decisionExplanation}

  // Remembered, so the hub knows and closing the tab does not undo it.
  $: if (missionComplete) recordCompletion('units-measurement');
</script>
<svelte:head><title>Units and Measurement | Qubix University</title><meta name="description" content="Local AI draft of a Qubix Superstore measurement-unit data quality mission." /></svelte:head>
<section class="mission-shell qx-shell"><MissionMasthead eyebrow={`${UNITS_MEASUREMENT_MISSION.id} · GOODS-IN ASSIGNMENT`} title={UNITS_MEASUREMENT_MISSION.title} roomId="goods-in" roomName="Goods In · Platform scale" progress={progress} meta={`${missionComplete ? UNITS_MEASUREMENT_MISSION.cases.length : caseIndex + 1} OF ${UNITS_MEASUREMENT_MISSION.cases.length} MEASUREMENTS`} />
  <main><section class="workbench m1-workarea"><div class="bar"><div><i></i><i></i><i></i></div><b>Qubix Measurement Normaliser</b><em>{missionComplete?'audit saved':caseRecord.table}</em></div>
    {#if missionComplete}<div class="complete-stage"><div class="seal">✓</div><p>BRANCH FEED QUALITY CHECK</p><h2>Measurements normalised</h2><span>Every original value remains traceable. The incompatible field is quarantined instead of being disguised as a conversion.</span></div>
    {:else}<div class="case-head"><div><p>CASE {caseIndex+1} OF {UNITS_MEASUREMENT_MISSION.cases.length} · {caseRecord.source}</p><h2>{caseRecord.item}</h2></div><span class:blocked={caseRecord.normalisedValue===null}>{caseRecord.normalisedValue===null?'SCHEMA CONFLICT':'READY TO CHECK'}</span></div>
      <div class="pipeline" aria-label="Measurement conversion pipeline"><article class:active={step==='dimension'}><small>01 · SOURCE</small><strong>{caseRecord.rawValue} <b>{caseRecord.rawUnit}</b></strong><span>raw_value · retained</span></article><div class="arrow">→</div><article class:active={step==='value'} class:error={caseRecord.normalisedValue===null&&step!=='dimension'}><small>02 · NORMALISE</small><strong>{step==='dimension'?'?':caseRecord.factor}</strong><span>declared conversion</span></article><div class="arrow">→</div><article class:active={step==='decision'} class:error={caseRecord.normalisedValue===null&&step!=='dimension'}><small>03 · TARGET</small><strong>{step==='dimension'?'?':caseRecord.displayValue}</strong><span>{caseRecord.field} · expects {caseRecord.targetUnit}</span></article></div>
      <section class="schema"><div><small>REQUIRED FIELD</small><code>{caseRecord.table}.{caseRecord.field}</code></div><div><small>REQUIRED UNIT</small><b>{caseRecord.targetUnit}</b></div><div><small>DETECTED QUANTITY</small><b>{step==='dimension'?'pending':caseRecord.dimension}</b></div></section>
      <section class="audit"><div class="audit-head"><b>Immutable audit preview</b><span>{step==='decision'?'complete':'building'}</span></div><pre>{`source_value:      ${caseRecord.rawValue} ${caseRecord.rawUnit}\nnormalised_value:  ${step==='dimension'?'—':caseRecord.displayValue}\ntreatment:         ${step==='decision'?caseRecord.decision:'—'}\nsource_system:     ${caseRecord.source}`}</pre></section>{/if}</section>
    <aside class="lesson-card">{#if missionComplete}<div class="completion"><span>✓</span><p class="eyebrow">COMPETENCY DEMONSTRATED</p><h2>Evidence preserved</h2><p>{UNITS_MEASUREMENT_MISSION.competency}</p><ul>{#each completed as entry}<li><b>{entry.field}</b><span>{entry.source_value}</span><em>{entry.normalised_value??'quarantined'}</em></li>{/each}</ul><a class="next-mission" href="?mode=game&mission=data-lineage">Continue to Mission 007</a><button on:click={resetMission}>Run mission again</button></div>
      {:else}<div class="step-meta"><span>THEORY → PRACTICAL</span><span>{stepIndex+1} / 3</span></div><p class="eyebrow">{step.toUpperCase()} CHECK</p><h2>{prompt}</h2><p class="theory">{theory}</p><article class="context">{caseRecord.context}</article><div class="options">{#each options as option}<button class:selected={selected===option.value} class:right={correct&&selected===option.value} class:wrong={checked&&!correct&&selected===option.value} on:click={()=>choose(option.value)} disabled={correct}><b>{option.label}</b><span>{option.note}</span></button>{/each}</div>{#if checked}<div class:success={correct} class:retry={!correct} class="feedback" role="status">{#if correct}<b>Correct.</b> {explanation()}{:else}<b>Try again.</b> Check the quantity first, then change the number and unit together.{/if}</div>{/if}{#if correct}<button class="continue" on:click={advance}>{step==='dimension'?'Calculate the target value':step==='value'?'Choose a treatment':caseIndex===UNITS_MEASUREMENT_MISSION.cases.length-1?'Complete mission':'Save audit entry'} →</button>{/if}{/if}</aside></main>
  <footer><span>Source-informed learning draft · accessed 22 August 2026</span><span>{#each UNITS_MEASUREMENT_MISSION.sources as source,index}<a href={source.url} target="_blank" rel="noreferrer">{source.label}</a>{index<UNITS_MEASUREMENT_MISSION.sources.length-1?' · ':''}{/each}</span></footer></section>
<style>
  :global(.qubix-university){height:auto!important;overflow:visible!important}
  :global(html),:global(body),:global(#app){height:auto!important;min-height:100%;overflow:visible!important;background:#171510}:global(body){position:static}.mission-shell{min-height:100vh;max-width:none;padding:18px clamp(12px,3vw,34px) 30px;background:radial-gradient(circle at 42% 0,#3f3428,#171510 58%);overflow:auto;color:#f1ede4}header{max-width:1340px;margin:0 auto 14px;display:flex;align-items:center;justify-content:space-between;gap:16px}.identity{display:flex;align-items:center;gap:12px}.role{display:grid;place-items:center;width:48px;height:48px;border-radius:13px;background:#a85a34;color:#fff;font:900 12px/1.15 var(--qx-font);text-align:center}.identity p{margin:0 0 3px;color:#aebbbb;font:800 12px var(--qx-font);letter-spacing:.1em}.identity h1{margin:0;color:#fff;font:700 26px Georgia,serif}nav{display:flex;gap:14px}nav a,footer a{color:#dfc1b3;font:800 13.5px var(--qx-font);text-decoration:none;border-bottom:1px solid currentColor;padding-bottom:3px}.progress{max-width:1340px;height:5px;margin:0 auto 16px;border-radius:8px;background:rgba(255,255,255,.1);overflow:hidden}.progress span{display:block;height:100%;background:#63b13b;transition:width .35s ease}main{max-width:1340px;margin:0 auto;display:grid;grid-template-columns:minmax(0,1.25fr) minmax(360px,.75fr);gap:16px;align-items:start}.workbench,.lesson-card{border:1px solid rgba(255,255,255,.14);border-radius:17px;overflow:hidden}.workbench{min-height:690px;background:#edf1ed;color:#202727}.bar{height:44px;padding:0 14px;display:flex;align-items:center;gap:10px;background:#202a2b;color:#e4e9e6}.bar>div{display:flex;gap:6px}.bar i{width:9px;height:9px;border-radius:50%;background:#a85a34}.bar i:nth-child(2){background:#d39a35}.bar i:nth-child(3){background:#5c9b52}.bar b{font:800 13px var(--qx-font)}.bar em{margin-left:auto;color:#9cacab;font:700 12px var(--qx-font)}.case-head{padding:22px 24px;display:flex;justify-content:space-between;align-items:center;gap:14px;border-bottom:1px solid #ccd5d0}.case-head p{margin:0 0 4px;color:#677774;font:900 11.5px var(--qx-font);letter-spacing:.1em}.case-head h2{margin:0;font:700 25px Georgia,serif}.case-head>span{padding:8px 10px;border-radius:18px;background:#dfead9;color:#477738;font:900 11.5px var(--qx-font);letter-spacing:.06em}.case-head>span.blocked{background:#f1d9d3;color:#96392b}.pipeline{display:grid;grid-template-columns:1fr 32px 1fr 32px 1fr;align-items:center;padding:35px 24px}.pipeline article{min-height:135px;padding:16px;display:flex;flex-direction:column;justify-content:center;border:2px solid #cad4cf;border-radius:13px;background:#fff;box-shadow:0 6px 18px rgba(35,57,55,.06)}.pipeline article.active{border-color:#a85a34;box-shadow:0 0 0 4px rgba(168,90,52,.12)}.pipeline article.error{border-color:#b94b3b;background:#fbefec}.pipeline small,.schema small{color:#71807c;font:900 11.5px var(--qx-font);letter-spacing:.1em}.pipeline strong{margin:11px 0;color:#332c24;font:800 20px/1.25 var(--qx-font);overflow-wrap:anywhere}.pipeline strong b{color:#a85a34}.pipeline article span{color:#71807c;font:700 12px var(--qx-font)}.arrow{text-align:center;color:#768783;font:900 22px var(--qx-font)}.schema{margin:0 24px;padding:14px;display:grid;grid-template-columns:1.5fr .7fr 1fr;gap:12px;border:1px solid #cad4cf;border-radius:12px;background:#dfe7e2}.schema div{display:grid;gap:6px}.schema code,.schema b{font:800 13.5px var(--qx-font)}.audit{margin:18px 24px 24px;border:1px solid #283736;border-radius:11px;overflow:hidden;background:#211c17;color:#cfdbd6}.audit-head{padding:10px 13px;display:flex;justify-content:space-between;background:#283735}.audit-head b,.audit-head span{font:800 11.5px var(--qx-font);letter-spacing:.08em}.audit-head span{color:#8fc17a}.audit pre{margin:0;padding:15px;white-space:pre-wrap;font:600 13.5px/1.7 Consolas,monospace}.lesson-card{padding:clamp(18px,2.4vw,28px);background:#f1ede4;color:#25231f;overflow:visible}.step-meta{display:flex;justify-content:space-between;margin-bottom:15px;color:#706858;font:900 11.5px var(--qx-font);letter-spacing:.09em}.eyebrow{margin:0 0 7px;color:#8c4c2e;font:900 12px var(--qx-font);letter-spacing:.12em}.lesson-card h2,.completion h2{margin:0;font:700 23px Georgia,serif}.theory,.completion>p{margin:8px 0 14px;color:#625a49;font:600 14.5px/1.5 var(--qx-font)}.context{margin-bottom:13px;padding:12px;border:1px solid #d8d0be;border-radius:10px;background:#fbf8f1;font:650 13.5px/1.45 var(--qx-font)}.options{display:grid;gap:8px}.options button{min-height:59px;padding:10px 12px;border:2px solid #ded6c6;border-radius:11px;background:#fff;color:#25231f;text-align:left;cursor:pointer}.options button b,.options button span{display:block}.options button b{font:850 13.5px/1.3 var(--qx-font)}.options button span{margin-top:4px;color:#736a59;font:600 12px/1.3 var(--qx-font)}.options button:hover,.options button.selected{border-color:#a85a34}.options button.right{border-color:#559535;background:#e7f0df}.options button.wrong{border-color:#b83a29;background:#f6ddd8}.options button:focus-visible,.continue:focus-visible,.completion button:focus-visible{outline:3px solid #a85a34;outline-offset:2px}.options button:disabled{cursor:default}.feedback{margin-top:11px;padding:11px 12px;border-radius:10px;font:650 13.5px/1.45 var(--qx-font)}.feedback.success{background:#e7f0df;color:#3d6529}.feedback.retry{background:#f6ddd8;color:#912c1e}.continue,.completion button{width:100%;min-height:46px;margin-top:11px;border:0;border-radius:11px;background:#a85a34;color:#fff;font:900 13.5px var(--qx-font);cursor:pointer}.completion{text-align:center}.completion>span,.seal{display:grid;place-items:center;width:58px;height:58px;margin:10px auto 14px;border-radius:50%;background:#559535;color:#fff;font:900 26px var(--qx-font)}.completion ul{list-style:none;margin:20px 0 0;padding:0;border:1px solid #d8d0be;border-radius:11px;overflow:hidden;text-align:left}.completion li{display:grid;grid-template-columns:1.1fr .8fr .8fr;gap:8px;padding:10px;border-bottom:1px solid #ddd5c5;font:700 12px var(--qx-font)}.completion li:last-child{border-bottom:0}.completion li span{color:#6f6758}.completion li em{color:#8c4c2e;text-align:right}.complete-stage{min-height:645px;padding:30px;display:grid;place-content:center;text-align:center}.complete-stage p{margin:0 0 6px;color:#55756f;font:900 12px var(--qx-font);letter-spacing:.12em}.complete-stage h2{margin:0 0 9px;font:700 29px Georgia,serif}.complete-stage>span{max-width:500px;color:#61706c;font:650 14.5px/1.5 var(--qx-font)}footer{max-width:1340px;margin:14px auto 0;display:flex;justify-content:space-between;gap:14px;color:#91a09d;font:650 12px/1.5 var(--qx-font)}footer a{font-size:12px}@media(max-width:1000px){main{grid-template-columns:1fr}.workbench{min-height:0}footer{flex-direction:column}}@media(max-width:650px){.mission-shell{padding:13px 10px 25px}header{align-items:flex-start}.identity h1{font-size:20px}.role{width:42px;height:42px}nav{flex-direction:column;align-items:flex-end;gap:6px}.pipeline{grid-template-columns:1fr;padding:18px}.arrow{transform:rotate(90deg)}.schema{grid-template-columns:1fr;margin:0 18px}.audit{margin:18px}.lesson-card{padding:16px}.completion li{grid-template-columns:1fr}.completion li em{text-align:left}}@media(prefers-reduced-motion:reduce){.progress span{transition:none}}
  .next-mission{display:grid;place-items:center;box-sizing:border-box;width:100%;min-height:46px;margin-top:11px;border-radius:11px;background:#25231f;color:#fff;font:900 13.5px var(--qx-font);text-decoration:none}.next-mission:focus-visible{outline:3px solid #a85a34;outline-offset:2px}
</style>
